new:
payUndoable(
  entity,
  other ? SKILL_SWAP_GOLD + 1 : SKILL_SWAP_GOLD,
  entity._online === true ? accountOfSave(entity, REALM_EMPIRE_ACCOUNT) : null,
);

if (resetGold(entity) < SKILL_SWAP_GOLD)
  return t('skillswap.refuse.gold', 'Changing a class skill costs {gold, number} gold. You have {have, number}.', {
    gold: SKILL_SWAP_GOLD,
    have: resetGold(entity),
  });
if (isMasteredSkill(entity, out)) return t('skillswap.refuse.mastered', 'A mastered skill stays in your class.');
